def compute(vars):
    amount = vars["v1"]
    settlements = vars["v2"]
    result = amount - settlements
    return {
        "value": result,
        "trace": {
            "amount_at_december_31_2008": amount,
            "settlements": settlements,
            "amount_without_settlements": result,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
